template.value:
// ==================== TEXT ====================

// String
@Column(nullable = false, length = 100)
private String name;

// String largo
@Column(columnDefinition = "TEXT")
private String description;


// ==================== NUMBERS ====================

// Integer
private Integer quantity;
// Long
private Long externalId;

// Decimal / dinero
@Column(precision = 19, scale = 2)
private BigDecimal amount;

// ==================== BOOLEAN ====================

// Boolean
@Column(nullable = false)
private Boolean active;

// ==================== ENUM ====================

@Enumerated(EnumType.STRING)
@Column(nullable = false, length = 30)
private Status status;

// ==================== DATE / TIME ====================

// Fecha y hora
private LocalDateTime dateTime;

// Solo fecha
private LocalDate date;

// Solo hora
private LocalTime time;

// ==================== UUID ====================

// UUID
@Column(nullable = false, unique = true)
private UUID uuid;

// ==================== AUDIT ====================

// Fecha de creación
@CreationTimestamp
@Column(nullable = false, updatable = false)
private LocalDateTime createdAt;

// Fecha de actualización
@UpdateTimestamp
@Column(nullable = false)
private LocalDateTime updatedAt;

// ==================== RELATIONSHIPS ====================

// ManyToOne
@ManyToOne(fetch = FetchType.LAZY, optional = false)
@JoinColumn(name = "...")
private SomeEntity someEntity;

// OneToMany
@OneToMany(
  mappedBy = "...",
  cascade = CascadeType.ALL,
  orphanRemoval = true
)
private List<SomeEntity> items = new ArrayList<>();

// WHERE
// Busca por un campo.
Optional<UserEntity> findByEmail(String email);

// EXISTS
// Verifica si existe al menos un registro.
boolean existsByEmail(String email);

// AND
// Filtra por múltiples campos.
List<UserEntity> findByNameAndActive(
        String name,
        boolean active);

// OR
// Busca cuando se cumple una condición u otra.
Optional<UserEntity> findByEmailOrUsername(
        String email,
        String username);

// CONTAINING
// Busca coincidencias parciales.
List<UserEntity> findByNameContaining(String name);

// IGNORE CASE
// Busca sin distinguir mayúsculas/minúsculas.
List<UserEntity> findByNameContainingIgnoreCase(String name);

// TRUE / FALSE
// Filtra campos booleanos.
List<UserEntity> findByActiveTrue();

// IN
// Busca valores dentro de una lista.
List<UserEntity> findByStatusIn(
        List<UserStatus> statuses);

// BETWEEN
// Busca valores dentro de un rango.
List<UserEntity> findByCreatedAtBetween(
        LocalDateTime start,
        LocalDateTime end);

// COUNT
// Cuenta registros que cumplen una condición.
long countByStatus(UserStatus status);


// ORDER BY
// Filtra y ordena resultados.
List<UserEntity> findByActiveTrueOrderByCreatedAtDesc();


// TOP
// Limita la cantidad de resultados.
List<UserEntity> findTop10ByActiveTrueOrderByCreatedAtDesc();

$END$

//Úsado para consultas personalizadas o complejas.

// WHERE
// Filtra por una condición.
@Query("""
    SELECT u
    FROM UserEntity u
    WHERE u.email = :email
    """)
Optional<UserEntity> findByEmail(
        @Param("email") String email);

// AND
// Combina múltiples condiciones.
@Query("""
    SELECT u
    FROM UserEntity u
    WHERE u.active = true
    AND u.name = :name
    """)
List<UserEntity> findActiveByName(
        @Param("name") String name);

// LIKE
// Busca coincidencias parciales.
@Query("""
    SELECT u
    FROM UserEntity u
    WHERE LOWER(u.name)
    LIKE LOWER(CONCAT('%', :name, '%'))
    """)
List<UserEntity> searchByName(
        @Param("name") String name);

// BETWEEN
// Filtra un rango de valores.
@Query("""
    SELECT a
    FROM AppointmentEntity a
    WHERE a.date BETWEEN :start AND :end
    """)
List<AppointmentEntity> findBetween(
        @Param("start") LocalDateTime start,
        @Param("end") LocalDateTime end);

// IN
// Filtra valores dentro de una lista.
@Query("""
    SELECT u
    FROM UserEntity u
    WHERE u.status IN :statuses
    """)
List<UserEntity> findByStatuses(
        @Param("statuses") List<UserStatus> statuses);

// JOIN
// Relaciona entidades.
@Query("""
    SELECT a
    FROM AppointmentEntity a
    JOIN a.doctor d
    WHERE d.id = :doctorId
    """)
List<AppointmentEntity> findByDoctor(
        @Param("doctorId") Long doctorId);

// JOIN FETCH
// Carga la relación en la misma consulta.
@Query("""
    SELECT a
    FROM AppointmentEntity a
    JOIN FETCH a.doctor
    WHERE a.id = :id
    """)
Optional<AppointmentEntity> findByIdWithDoctor(
        @Param("id") Long id);

// COUNT
// Cuenta registros.
@Query("""
    SELECT COUNT(u)
    FROM UserEntity u
    WHERE u.active = true
    """)
long countActive();

// UPDATE
// Actualiza registros directamente.
@Modifying
@Query("""
    UPDATE UserEntity u
    SET u.active = false
    WHERE u.id = :id
    """)
int deactivate(@Param("id") Long id);

// DELETE
// Elimina registros directamente.
@Modifying
@Query("""
    DELETE FROM UserEntity u
    WHERE u.id = :id
    """)
int deleteByUserId(@Param("id") Long id);

$END$
